import { sql } from "drizzle-orm";
import { migrate as runMigrations } from "drizzle-orm/node-postgres/migrator";
import { fileURLToPath } from "node:url";
import type { Database } from "./client.js";

// packages/db/migrations, generated by drizzle-kit (tables) plus custom SQL (extensions, triggers).
const MIGRATIONS_FOLDER = fileURLToPath(new URL("../migrations", import.meta.url));

/** Applies pending migrations in order. Forward-only; applied history lives in drizzle.__drizzle_migrations. */
export async function migrate(db: Database): Promise<void> {
  await runMigrations(db, { migrationsFolder: MIGRATIONS_FOLDER });
}

/** Drops everything and re-applies all migrations. Development and tests only. */
export async function resetDatabase(db: Database): Promise<void> {
  await db.execute(sql`DROP SCHEMA IF EXISTS drizzle CASCADE`);
  await db.execute(sql`DROP SCHEMA public CASCADE`);
  await db.execute(sql`CREATE SCHEMA public`);
  await migrate(db);
}
